public class Course
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public int Hours { get; set; }

    [Timestamp]
    public byte[] RowVersion { get; set; } = [];
}

// UPDATE [Courses] SET [Hours] = @p0
// WHERE [Id] = @p1 AND [RowVersion] = @p2;

app.MapPut("/courses/{id:int}", async (int id, CourseEdit input, CollegeContext db) =>
{
    var course = await db.Courses.FindAsync(id);
    if (course is null) return Results.NotFound();

    db.Entry(course).Property(c => c.RowVersion).OriginalValue = input.RowVersion;
    course.Hours = input.Hours;

    try
    {
        await db.SaveChangesAsync();
        return Results.NoContent();
    }
    catch (DbUpdateConcurrencyException)
    {
        return Results.Conflict("Someone else changed this course. Reload and try again.");
    }
});

